import os
import re
import sys
import json
import shutil
import textwrap
from pathlib import Path

import requests
from bs4 import BeautifulSoup

OUTPUT_MP3 = Path("/root/audiobook.mp3")
WORKDIR = Path("/root/tts_work")
WORKDIR.mkdir(parents=True, exist_ok=True)

ESSAYS = [
    {
        "title": "Do Things that Don't Scale",
        "url": "https://paulgraham.com/ds.html",
    },
    {
        "title": "Founder Mode",
        "url": "https://paulgraham.com/foundermode.html",
    },
]

DROP_LINES = {
    "Want to start a startup?",
    "Get funded by",
    "Y Combinator",
    "Y Combinator.",
}


def fetch_html(url: str) -> str:
    headers = {"User-Agent": "Mozilla/5.0"}
    try:
        resp = requests.get(url, headers=headers, timeout=30)
        resp.raise_for_status()
        return resp.text
    except requests.exceptions.SSLError:
        if url.startswith("https://"):
            http_url = "http://" + url[len("https://"):]
            resp = requests.get(http_url, headers=headers, timeout=30)
            resp.raise_for_status()
            return resp.text
        raise


def extract_text(html: str) -> str:
    soup = BeautifulSoup(html, "lxml")
    for tag in soup(["script", "style"]):
        tag.decompose()

    text = soup.get_text("\n")
    raw_lines = [ln.strip() for ln in text.splitlines()]

    cleaned = []
    for line in raw_lines:
        if not line:
            if cleaned and cleaned[-1] != "":
                cleaned.append("")
            continue
        if line in DROP_LINES:
            continue
        if line in {"[", "]"}:
            continue
        if re.fullmatch(r"\[?\d+\]?", line):
            continue
        if line == "Translations" or line.endswith("Translation"):
            continue
        if line.startswith("Copyright"):
            continue
        cleaned.append(line)

    out = "\n".join(cleaned)
    out = re.sub(r"\n{3,}", "\n\n", out).strip()
    return out


def chunk_text(text: str, max_chars: int = 3200):
    paras = [p.strip() for p in text.split("\n\n") if p.strip()]
    chunks = []
    buf = ""
    for p in paras:
        if not buf:
            candidate = p
        else:
            candidate = buf + "\n\n" + p
        if len(candidate) <= max_chars:
            buf = candidate
            continue
        if buf:
            chunks.append(buf)
        # If paragraph itself is too big, hard split
        if len(p) > max_chars:
            start = 0
            while start < len(p):
                chunks.append(p[start:start + max_chars])
                start += max_chars
            buf = ""
        else:
            buf = p
    if buf:
        chunks.append(buf)
    return chunks


def openai_tts(text: str, out_path: Path, voice: str = "alloy"):
    api_key = os.environ.get("OPENAI_API_KEY")
    if not api_key:
        raise RuntimeError("OPENAI_API_KEY not set")

    url = "https://api.openai.com/v1/audio/speech"
    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json",
    }
    payload = {
        "model": "gpt-4o-mini-tts",
        "voice": voice,
        "input": text,
        "format": "mp3",
    }

    resp = requests.post(url, headers=headers, json=payload, timeout=120)
    resp.raise_for_status()
    out_path.write_bytes(resp.content)


def elevenlabs_tts(text: str, out_path: Path):
    api_key = os.environ.get("ELEVENLABS_API_KEY")
    if not api_key:
        raise RuntimeError("ELEVENLABS_API_KEY not set")

    voices_resp = requests.get(
        "https://api.elevenlabs.io/v1/voices",
        headers={"xi-api-key": api_key},
        timeout=30,
    )
    voices_resp.raise_for_status()
    voices = voices_resp.json().get("voices", [])
    if not voices:
        raise RuntimeError("No ElevenLabs voices available")
    voice_id = voices[0]["voice_id"]

    url = f"https://api.elevenlabs.io/v1/text-to-speech/{voice_id}"
    headers = {
        "xi-api-key": api_key,
        "Content-Type": "application/json",
    }
    payload = {
        "text": text,
        "model_id": "eleven_multilingual_v2",
    }

    resp = requests.post(url, headers=headers, json=payload, timeout=120)
    resp.raise_for_status()
    out_path.write_bytes(resp.content)


def local_tts(text: str, out_path: Path):
    import subprocess

    espeak = shutil.which("espeak") or shutil.which("espeak-ng")
    if not espeak:
        raise RuntimeError("No local TTS engine found (espeak/espeak-ng)")

    wav_path = out_path.with_suffix(".wav")
    text_path = out_path.with_suffix(".txt")
    text_path.write_text(text, encoding="utf-8")

    subprocess.run([espeak, "-f", str(text_path), "-w", str(wav_path)], check=True)
    subprocess.run(["ffmpeg", "-y", "-i", str(wav_path), str(out_path)], check=True)


def synthesize_chunks(chunks, out_dir: Path):
    out_dir.mkdir(parents=True, exist_ok=True)
    segment_paths = []

    for i, chunk in enumerate(chunks, start=1):
        seg_path = out_dir / f"seg_{i:04d}.mp3"
        try:
            openai_tts(chunk, seg_path)
        except Exception as openai_err:
            try:
                elevenlabs_tts(chunk, seg_path)
            except Exception:
                local_tts(chunk, seg_path)
        segment_paths.append(seg_path)
    return segment_paths


def concat_mp3s(segment_paths, output_path: Path):
    list_file = output_path.with_suffix(".txt")
    with list_file.open("w", encoding="utf-8") as f:
        for p in segment_paths:
            f.write(f"file '{p.as_posix()}'\n")

    import subprocess
    subprocess.run(
        [
            "ffmpeg",
            "-y",
            "-f",
            "concat",
            "-safe",
            "0",
            "-i",
            str(list_file),
            "-c",
            "copy",
            str(output_path),
        ],
        check=True,
    )


def main():
    all_segments = []

    for essay in ESSAYS:
        html = fetch_html(essay["url"])
        text = extract_text(html)

        intro = f"Essay: {essay['title']}."
        outro = "End of essay."
        full_text = f"{intro}\n\n{text}\n\n{outro}"

        chunks = chunk_text(full_text, max_chars=3200)
        essay_dir = WORKDIR / re.sub(r"[^a-z0-9]+", "-", essay["title"].lower()).strip("-")
        segments = synthesize_chunks(chunks, essay_dir)
        all_segments.extend(segments)

    concat_mp3s(all_segments, OUTPUT_MP3)


if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        print(f"Error: {exc}", file=sys.stderr)
        sys.exit(1)
